cp src/claim-office.ts /tmp/trial-backup.ts && python3 - <<'EOF'
import re
p='src/claim-office.ts'
s=open(p).read()
old='''// The net rate of the spec's policy-wide clauses: loyalty, first insurance and
// (not yet priced) the follow-up-contract discount. Each is stated as a signed
// percentage and they compose additively, so one net rate carries them; this is
// the one place a policy-wide clause is declared. Discounts subtract.
function policyModifierRate(customer: Customer): number {
  let rate = FIRST_INSURANCE_SURCHARGE_RATE;
  if (isLongStandingCustomer(customer)) {
    rate -= LOYALTY_DISCOUNT_RATE;
  }
  return rate;
}'''
new='''// Answers the spec's open question -- does "a first insurance" mean the
// customer's first ever contract, or the first time we see this particular
// item? -- in favour of the item. The spec's second integration example
// decides it: a 3-year customer's second contract for a brand-new sword is
// still charged the surcharge, "each item in a `quote` is treated as a first
// insurance, regardless of customer history". So every quote qualifies, and
// the predicate is unconditionally true rather than absent: the MHPCO has
// ruled on this, it is not an unhandled case. Who qualifies is a separate
// decision from what the clauses add up to -- the MHPCO could reverse the
// ruling and tie the surcharge to customer history without touching any
// clause's rate. This is the one place that category is decided.
function isFirstInsurance(items: readonly Item[]): boolean {
  return true;
}

// The net rate of the spec's policy-wide clauses: loyalty, first insurance and
// (not yet priced) the follow-up-contract discount. Each is stated as a signed
// percentage and they compose additively, so one net rate carries them; this is
// the one place a policy-wide clause is declared. Discounts subtract.
function policyModifierRate(customer: Customer, items: readonly Item[]): number {
  let rate = 0;
  if (isFirstInsurance(items)) {
    rate += FIRST_INSURANCE_SURCHARGE_RATE;
  }
  if (isLongStandingCustomer(customer)) {
    rate -= LOYALTY_DISCOUNT_RATE;
  }
  return rate;
}'''
assert old in s
s=s.replace(old,new)
s=s.replace('return policyBasePremium(items) * policyModifierRate(customer);','return policyBasePremium(items) * policyModifierRate(customer, items);')
open(p,'w').write(s)
EOF
